-- Owner runs after catalogue schema migration. Primary board responses and Saudi locations are recorded in research/job-catalogue-verified-2026-11-16.json.
on conflict(source,token) do update set catalog_enabled=true,board_verified_at=excluded.board_verified_at,board_verification_source=excluded.board_verification_source,
 company_category=case when ats_companies.company_category='unclassified' then excluded.company_category else ats_companies.company_category end,
 sector=coalesce(ats_companies.sector,excluded.sector),
 classification_source=coalesce(ats_companies.classification_source,excluded.classification_source),
 classification_verified_at=coalesce(ats_companies.classification_verified_at,excluded.classification_verified_at);
